/* ================================================================
   GRAFIK GILLETTE - CALENDAR.CSS
   Part of modular CSS split (v3.8.0)
   ================================================================ */

/* === CALENDAR === */
.calendar-wrap {
  overflow: visible;
}
.calendar {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 4px;
  margin-top: 6px;
  animation: slideIn 0.3s ease-out;
}
@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateX(-10px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
.slide-right {
  animation: slideRight 0.3s ease-out;
}
.slide-left {
  animation: slideLeft 0.3s ease-out;
}
@keyframes slideRight {
  from {
    opacity: 0;
    transform: translateX(30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
@keyframes slideLeft {
  from {
    opacity: 0;
    transform: translateX(-30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
/* Zapewnij, że kalendarz mieści się w kontenerze bez łamania popupów */
.calendar {
  width: 100%;
  box-sizing: border-box;
}

.day-header {
  text-align: center;
  font-weight: bold;
  padding: 6px;
  background: linear-gradient(180deg, #4b5563, #374151);
  color: #f3f4f6;
  border-radius: 6px;
  font-size: 13px;
}
body:not(.theme-dark) .day-header {
  background: linear-gradient(180deg, #e5e7eb, #d1d5db);
  color: #1f2937;
}
.day-header.weekend {
  background: linear-gradient(180deg, #4b5563, #374151);
  color: #fca5a5;
  box-shadow: inset 0 -2px 0 #ef4444;
  text-shadow: none;
}
body:not(.theme-dark) .day-header.weekend {
  background: linear-gradient(180deg, #e5e7eb, #d1d5db);
  color: #b91c1c;
  box-shadow: inset 0 -2px 0 #ef4444;
}

.day-cell {
  min-height: 74px;
  border: 1px solid var(--border-cell);
  border-radius: 8px;
  padding: 5px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background: var(--bg-cell);
  cursor: pointer;
  transition:
    transform 0.15s,
    box-shadow 0.15s,
    filter 0.15s;
  color: var(--text-main);
  position: relative;
}
/* Zapewnij, że komórki dni nie wymuszają rozszerzania kolumn siatki (naprawia miesiące z za dużymi komórkami) */
.day-cell {
  min-width: 0;
}
.day-cell:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px var(--shadow-color);
  filter: brightness(1.06);
  z-index: 20;
}
.day-cell.empty {
  background: transparent;
  border: none;
  cursor: default;
}

.day-cell.today {
  /* Usuń ozdobną kropkę; zamiast tego użyj kontrastującego obramowania */
  box-shadow: none;
}

/* Ukryj poprzedni znacznik kropki, jeśli jest obecny */
.day-cell.today::before {
  display: none;
}

/* Kontrastujące obramowanie: stały, jasny żółty (#f1c40f) widoczny na każdej
   temacie — zarówno na ciemnym, jak i na jasnym tle zmian (R,P,N,W,U) */
.day-cell.cell-R.today,
.day-cell.cell-P.today,
.day-cell.cell-N.today,
.day-cell.cell-W.today,
.day-cell.urlop.today,
.day-cell.today:not([class*='cell-']) {
  outline: 3px solid #f1c40f;
  outline-offset: 2px;
  box-shadow: 0 0 0 3px rgba(241, 196, 15, 0.4);
}

.day-cell.selected {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
  z-index: 20;
  box-shadow:
    0 0 0 3px rgba(255, 87, 34, 0.25),
    0 4px 15px var(--shadow-color);
}

body.edit-active .day-cell:not(.empty) {
  cursor: crosshair;
  box-shadow: inset 0 0 0 1px rgba(230, 126, 34, 0.5);
}
body.edit-active .day-cell:not(.empty):hover {
  outline: 2px solid #e67e22;
  outline-offset: -2px;
  transform: scale(1.04);
}

/* Style E: full factory fill for shifts; empty/dashed free days */
.day-cell.cell-R {
  background: var(--color-R);
  color: var(--color-R-text, #fff);
  border-color: var(--color-R-border);
}
.day-cell.cell-P {
  background: var(--color-P);
  color: var(--color-P-text, #fff);
  border-color: var(--color-P-border, var(--color-P));
}
.day-cell.cell-N {
  background: var(--color-N);
  color: var(--color-N-text, #fff);
  border-color: var(--color-N-border, var(--color-N));
}
.day-cell.cell-R::after,
.day-cell.cell-P::after,
.day-cell.cell-N::after {
  display: none;
}
.day-cell.cell-R .day-num,
.day-cell.cell-P .day-num,
.day-cell.cell-N .day-num,
.day-cell.cell-R .day-shift,
.day-cell.cell-P .day-shift,
.day-cell.cell-N .day-shift {
  color: inherit;
  font-weight: 700;
  text-shadow: 0 1px 1px rgba(0, 0, 0, 0.12);
