  display: inline-block;
  background: #f1c40f;
  color: #1a1a1a;
  padding: 3px 10px;
  border-radius: 8px;
  font-weight: 700;
  font-size: 12px;
  animation: dirtyPulse 1.5s infinite;
}
@keyframes dirtyPulse {
  0%,
  100% {
    transform: scale(1);
    box-shadow: 0 0 0 rgba(241, 196, 15, 0.5);
  }
  50% {
    transform: scale(1.05);
    box-shadow: 0 0 12px rgba(241, 196, 15, 0.7);
  }
}

/* === Discard + year on one row (mobile-friendly) === */
.ebg-row-discard-year {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1 1 auto;
  min-width: 0;
}
.ebg-row-discard-year #discardChangesBtn {
  flex: 1 1 auto;
  min-width: 0;
}
.ebg-row-discard-year .year-picker {
  flex: 0 0 auto;
  margin: 0;
}

/* === Responsive edit-banner для мобільних === */


/* === TOAST === */
.toast-container {
  position: fixed;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 200;
  display: flex;
  flex-direction: column-reverse;
  gap: 8px;
  pointer-events: none;
  max-width: 90vw;
}
.toast {
  background: var(--bg-container);
  color: var(--text-main);
  padding: 12px 20px;
  border-radius: 10px;
  box-shadow: 0 6px 25px var(--shadow-heavy);
  border-left: 4px solid var(--text-header);
  font-weight: 600;
  font-size: 14px;
  min-width: 250px;
  display: flex;
  align-items: center;
  gap: 10px;
  animation: toastIn 0.3s ease-out;
  pointer-events: all;
}
.toast.toast-out {
  animation: toastOut 0.3s ease-out forwards;
}
.toast.success {
  border-left-color: #27ae60;
}
.toast.error {
  border-left-color: #c0392b;
}
.toast.warn {
  border-left-color: #e67e22;
}
.toast.info {
  border-left-color: #3498db;
}
.toast .toast-icon {
  font-size: 20px;
  flex-shrink: 0;
}
@keyframes toastIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes toastOut {
  to {
    opacity: 0;
    transform: translateY(20px);
  }
}

/* === MODAL === */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.7);
  z-index: 150;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: fadeIn 0.25s ease-out;
}
.modal-overlay.show {
  display: flex;
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.modal {
  background: var(--bg-container);
  color: var(--text-main);
  border-radius: 16px;
  max-width: 500px;
  width: 100%;
  box-shadow: 0 25px 70px rgba(0, 0, 0, 0.5);
  animation: slideUp 0.3s ease-out;
  overflow: hidden;
}
@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
.modal-header {
  padding: 18px 22px 12px;
  border-bottom: 1px solid var(--border-cell);
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.modal-header h3 {
  margin: 0;
  color: var(--text-header);
  font-size: 18px;
}
.modal-close {
  background: transparent;
  border: none;
  font-size: 24px;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.modal-close:hover {
  background: #c0392b;
  color: #fff;
}
.modal-body {
  padding: 20px 22px;
  font-size: 14px;
  line-height: 1.5;
  max-height: 60vh;
  overflow-y: auto;
}
.modal-body p {
  margin: 0 0 12px;
}
.modal-body ul {
  margin: 8px 0;
  padding-left: 22px;
}

.faq-item {
  background: var(--bg-cell);
  border-radius: 10px;
  border: 1px solid var(--border-cell);
  overflow: hidden;
  transition: all 0.2s;
}
.faq-item[open] {
  box-shadow: 0 4px 15px var(--shadow-color);
  border-color: var(--text-header);
}
.faq-item summary {
  padding: 12px 16px;
  cursor: pointer;
  font-weight: 600;
  font-size: 14px;
  color: var(--text-header);
  list-style: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  transition: background 0.15s;
  user-select: none;
}
.faq-item summary::-webkit-details-marker {
  display: none;
}
.faq-item summary::after {
  content: '+';
  font-size: 20px;
  font-weight: bold;
  color: var(--text-muted);
  margin-left: 10px;
  transition: transform 0.2s;
}
.faq-item[open] summary::after {
  content: '−';
  color: var(--text-header);
}
.faq-item summary:hover {
  background: var(--bg-controls);
}
.faq-answer {
  padding: 5px 16px 16px;
  font-size: 13px;
  line-height: 1.55;
  color: var(--text-main);
  border-top: 1px solid var(--border-cell);
  margin-top: 5px;
  padding-top: 12px;
}
.faq-answer ul,
.faq-answer ol {
  margin: 8px 0;
  padding-left: 22px;
}
.faq-answer li {
  margin: 4px 0;
}

.modal-footer {
  padding: 12px 22px 18px;
  display: flex;
  gap: 10px;
  justify-content: flex-end;
  flex-wrap: wrap;
}
/* Sync modal: keep Cancel / Download / Send on a single row */
.modal-footer.modal-footer-single-row {
  flex-wrap: nowrap;
  gap: 6px;
  justify-content: stretch;
}
.modal-footer.modal-footer-single-row .modal-btn {
  flex: 1 1 0;
  min-width: 0;
  padding: 10px 8px;
  font-size: 13px;
  white-space: nowrap;
  text-align: center;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
}
.modal-footer.modal-footer-single-row .modal-btn-icon {
  flex-shrink: 0;
  display: block;
}
.modal-btn {
  padding: 10px 20px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  font-weight: 600;
  font-size: 14px;
  transition: all 0.15s;
}
.modal-btn.primary {
  background: var(--text-header);
  color: #fff;
}
.modal-btn.primary:hover {
  filter: brightness(1.15);
}
.modal-btn.danger {
  background: #c0392b;
  color: #fff;
}
.modal-btn.danger:hover {
  background: #a93226;
}
.modal-btn.success {
  background: #27ae60;
  color: #fff;
}
.modal-btn.success:hover {
  background: #229954;
}
.modal-btn.secondary {
  background: var(--bg-controls);
  color: var(--text-main);
  border: 1px solid var(--border-cell);
}
.modal-btn.secondary:hover {
  background: var(--bg-cell);
}

/* === PALETTE BUTTONS (new set) === */
