}


/* === FOOTER === */
.app-footer {
  margin-top: 25px;
  padding-top: 15px;
  border-top: 1px solid var(--border-cell);
  text-align: center;
  font-size: 12px;
  color: var(--text-muted);
  display: flex;
  flex-direction: column;
