/* === TOP BAR === */

/* === LANGUAGE DROPDOWN === */
.lang-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  background: var(--bg-container);
  border: 2px solid var(--border-cell);
  border-radius: 12px;
  padding: 6px;
  box-shadow: 0 8px 30px var(--shadow-heavy);
  z-index: 100;
  display: none;
  flex-direction: column;
  gap: 4px;
  min-width: 140px;
}
.lang-dropdown.show {
  display: flex;
}
.top-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  margin-bottom: 15px;
  position: relative;
}


.lang-option {
  background: transparent;
  border: none;
  padding: 8px 12px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-main);
  text-align: left;
  transition: all 0.15s;
  display: flex;
  align-items: center;
  gap: 8px;
}
.lang-option:hover {
  background: var(--bg-controls);
  color: var(--text-header);
  transform: translateX(2px);
}
.lang-option.active {
  background: var(--text-header);
  color: #fff;
  box-shadow: 0 2px 8px var(--shadow-color);
}
.top-bar h1 {
  text-align: center;
  color: var(--text-header);
  margin: 0;
  font-size: 22px;
  flex: 1;
}
.icon-btn {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  border: 2px solid var(--border-cell);
  background: var(--bg-controls);
  color: var(--text-header);
  cursor: pointer;
  font-size: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
  flex-shrink: 0;
}
.icon-btn:hover {
  background: var(--text-header);
  color: #fff;
  transform: scale(1.08);
}

#userAuthBtn.auth-logged-in {
  background: #2ecc71;
  color: #fff;
  border-color: #27ae60;
}

#userAuthBtn.auth-logged-in:hover {
  background: #27ae60;
}
.icon-btn.edit-active {
  background: linear-gradient(135deg, #e67e22, #d35400);
  color: #fff;
  border-color: #d35400;
  animation: editPulse 2s infinite;
}
@keyframes editPulse {
  0%,
  100% {
    box-shadow: 0 2px 10px rgba(230, 126, 34, 0.5);
  }
  50% {
    box-shadow: 0 2px 20px rgba(230, 126, 34, 0.9);
  }
}

/* === SIDE MENU === */
.side-menu-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 90;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s;
}
.side-menu-overlay.show {
  opacity: 1;
  pointer-events: all;
}
.side-menu {
  position: fixed;
  top: 0;
  right: -320px;
  width: 300px;
  max-width: 90vw;
  height: 100vh;
  background: var(--bg-container);
  box-shadow: -4px 0 20px var(--shadow-heavy);
  padding: 20px;
  overflow-y: auto;
  transition: right 0.3s ease-out;
  z-index: 91;
  color: var(--text-main);
}
.side-menu.show {
  right: 0;
}
.side-menu h3 {
  color: var(--text-header);
  margin: 0 0 15px;
  font-size: 18px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.side-menu-close {
  background: transparent;
  border: none;
  font-size: 26px;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.side-menu-close:hover {
  background: #c0392b;
  color: #fff;
}
.menu-section {
  margin-bottom: 20px;
  padding-bottom: 15px;
  border-bottom: 1px solid var(--border-cell);
}
.menu-section:last-child {
  border-bottom: none;
}
.menu-section-title {
  font-size: 12px;
  text-transform: uppercase;
  color: var(--text-muted);
  letter-spacing: 1px;
  margin-bottom: 10px;
  font-weight: 700;
}
.menu-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px 12px;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  color: var(--text-main);
  font-size: 14px;
  font-weight: 600;
  text-align: left;
  margin: 3px 0;
  transition: all 0.15s;
}
.menu-item:hover {
  background: var(--bg-controls);
  border-color: var(--border-cell);
}
.menu-item.active {
  background: var(--bg-controls);
  border-color: var(--text-header);
  color: var(--text-header);
}
.menu-item .mi-icon {
  font-size: 18px;
  width: 24px;
  text-align: center;
}
.menu-item .mi-check {
  margin-left: auto;
  color: var(--text-header);
  font-weight: bold;
}

/* === MAIN CONTROLS === */
.controls-main {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
  align-items: center;
  margin-bottom: 14px;
  padding: 10px;
  background: var(--bg-controls);
  border-radius: 12px;
}
.shift-buttons {
  display: flex;
  gap: 4px;
  padding: 3px;
  background: var(--bg-container);
  border-radius: 10px;
}
.shift-btn {
  padding: 7px 14px;
  border: 2px solid transparent;
  border-radius: 8px;
  font-weight: bold;
  font-size: 15px;
  cursor: pointer;
  transition: all 0.2s;
  color: #fff;
  min-width: 40px;
}
.shift-btn.A {
  background: var(--brig-A);
}
.shift-btn.B {
  background: var(--brig-B);
}
.shift-btn.C {
  background: var(--brig-C);
}
.shift-btn.D {
  background: var(--brig-D);
}
.shift-btn.active {
  border-color: #f1c40f;
  transform: scale(1.1);
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.3);
}
.shift-btn.compare {
  border-color: var(--accent);
  border-style: dashed;
}

.year-picker {
  display: flex;
  align-items: center;
  gap: 2px;
  background: var(--bg-container);
  border: 2px solid var(--text-header);
  border-radius: 10px;
  padding: 3px 6px;
  font-weight: 700;
}
.year-picker button {
  background: transparent;
  border: none;
  color: var(--text-header);
  font-size: 22px;
  font-weight: bold;
  cursor: pointer;
  padding: 0 8px;
  line-height: 1;
  transition: transform 0.15s;
}
.year-picker button:hover {
  transform: scale(1.4);
}
.year-picker .year-current {
  min-width: 55px;
  text-align: center;
  color: var(--text-header);
  font-size: 16px;
  padding: 4px 0;
}
.year-picker.no-data {
  border-color: #e67e22;
  background: rgba(230, 126, 34, 0.15);
}
.year-picker.no-data .year-current::after {
  content: ' ✏️';
}

.btn-primary,
.btn-secondary {
  padding: 8px 14px;
  border-radius: 10px;
  border: none;
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  transition: all 0.15s;
}
.btn-primary {
  background: var(--text-header);
  color: #fff;
}
.btn-primary:hover {
  filter: brightness(1.15);
  transform: translateY(-1px);
}
.btn-secondary {
  background: var(--bg-container);
  color: var(--text-main);
  border: 1px solid var(--border-cell);
}
.btn-secondary:hover {
  background: var(--bg-cell);
}

/* === VIEW SWITCHER === */
.view-switcher {
  display: flex;
  gap: 4px;
  background: var(--bg-controls);
  padding: 4px;
  border-radius: 12px;
  margin-bottom: 15px;
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
  flex-wrap: wrap;
}
.view-btn {
  flex: 1 1 auto;
  min-width: 100px;
  padding: 8px 10px;
  background: transparent;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-main);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  transition: all 0.15s;
}
.view-btn:hover {
  background: var(--bg-cell);
}
.view-btn.active {
  background: var(--text-header);
  color: #fff;
  box-shadow: 0 2px 8px var(--shadow-color);
}
.year-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  background: var(--bg-container);
  border: 2px solid var(--border-cell);
  border-radius: 8px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-main);
  user-select: none;
  transition: all 0.15s;
  flex-shrink: 0;
}
.year-toggle:hover {
  border-color: var(--text-header);
  background: var(--bg-cell);
}
.year-toggle input[type='checkbox'] {
  width: 16px;
  height: 16px;
  cursor: pointer;
  accent-color: var(--text-header);
  margin: 0;
}
.year-toggle.active {
  background: var(--text-header);
  color: #fff;
  border-color: var(--text-header);
  box-shadow: 0 2px 8px var(--shadow-color);
}
.year-toggle.active span {
  color: #fff;
}
.year-toggle.disabled {
  opacity: 0.35;
  cursor: not-allowed;
  pointer-events: none;
}

