/* === NADGODZINY: ⏱ palette (50 gray · 100 purple · 200 red) + 3rd popup === */
.day-cell .ot-marker {
  position: absolute;
  top: 3px;
  right: 3px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  line-height: 1;
  z-index: 4;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.35);
  pointer-events: none;
}
.day-cell .ot-marker.ot-50 {
  background: linear-gradient(135deg, #95a5a6, #7f8c8d);
  color: #fff;
}
.day-cell .ot-marker.ot-100 {
  background: linear-gradient(135deg, #8e44ad, #6c3483);
  color: #fff;
}
.day-cell .ot-marker.ot-200 {
  background: linear-gradient(135deg, #c0392b, #922b21);
  color: #fff;
}

/* Third popup: cell-sized, above day; same hover/selected as .relief-popup */
.day-cell .ot-detail-popup {
  position: absolute;
  left: 0;
  right: 0;
  width: 100%;
  height: 100%;
  top: auto;
  bottom: 100%;
  min-width: 0;
  max-width: none;
  padding: 4px 3px;
  border-radius: inherit;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: #fff;
  text-align: center;
  z-index: 26;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.35);
  opacity: 0;
  visibility: hidden;
  transform: scale(0.96);
  pointer-events: none;
  transition:
    opacity 0.2s ease-out,
    transform 0.2s ease-out,
    visibility 0.2s;
  transition-delay: 0.6s;
}
.day-cell .ot-detail-popup.ot-50 {
  background: linear-gradient(135deg, #95a5a6, #7f8c8d);
}
.day-cell .ot-detail-popup.ot-100 {
  background: linear-gradient(135deg, #8e44ad, #6c3483);
}
.day-cell .ot-detail-popup.ot-200 {
  background: linear-gradient(135deg, #c0392b, #922b21);
}
.day-cell:hover .ot-detail-popup,
.day-cell.selected .ot-detail-popup {
  opacity: 1;
  visibility: visible;
  transform: scale(1);
  transition-delay: 0.6s;
}
.day-cell.selected .ot-detail-popup {
  transition-delay: 0s;
}
