/* ================================================================
   GRAFIK GILLETTE - SMART-POPUP.CSS
   Timeline widget for relief handoff visualization in info-panel
   Matches mockup U4 (Flow передачі зміни)
   Part of modular CSS split (v3.9.0+)
   ================================================================ */

/* === Timeline Widget Container === */
.timeline-widget {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 4px;
  flex-wrap: wrap;
}

/* === Timeline Node (brigade or OT block) === */
.tl-node {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 48px;
  padding: 6px 8px;
  border-radius: 8px;
  color: #fff;
  text-align: center;
  flex-shrink: 0;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25);
  transition: transform 0.15s;
}

.tl-node:hover {
  transform: translateY(-1px);
}

/* Node types by shift color */
.tl-node.tl-shift-R {
  background: linear-gradient(135deg, var(--color-R), var(--color-R-border));
  border: 1px solid var(--color-R-border);
}

.tl-node.tl-shift-P {
  background: linear-gradient(135deg, var(--color-P), var(--color-P-border));
  border: 1px solid var(--color-P-border);
}

.tl-node.tl-shift-N {
  background: linear-gradient(135deg, var(--color-N), var(--color-N-border));
  border: 1px solid var(--color-N-border);
}

/* Self node (current day, slightly larger + highlight border) */
.tl-node.tl-self {
  min-width: 54px;
  padding: 7px 10px;
  border: 2px solid rgba(255, 255, 255, 0.4);
}

/* OT node (red gradient by default / rate variants) */
.tl-node.tl-ot {
  background: linear-gradient(135deg, #c0392b, #922b21);
  border: 1px solid #922b21;
}

.tl-node.tl-ot-50 {
  background: linear-gradient(135deg, #95a5a6, #7f8c8d);
  border: 1px solid #7f8c8d;
}

.tl-node.tl-ot-100 {
  background: linear-gradient(135deg, #8e44ad, #6c3483);
  border: 1px solid #6c3483;
}

/* Empty node (no prev/next) */
.tl-node.tl-empty {
  background: linear-gradient(135deg, #7f8c8d, #576269);
  border: 1px solid #576269;
  opacity: 0.6;
}

/* === Node Content === */
.tl-brig {
  font-size: 18px;
  font-weight: 700;
  line-height: 1;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}

.tl-icon {
  font-size: 12px;
  margin-top: 2px;
  line-height: 1;
}

.tl-label {
  font-size: 9px;
  opacity: 0.9;
  margin-top: 2px;
  white-space: nowrap;
  font-weight: 500;
}

.tl-value {
  font-size: 14px;
  font-weight: 700;
  line-height: 1;
}

/* === Flow Arrow === */
.tl-arrow {
  font-size: 16px;
  color: var(--accent);
  font-weight: 700;
  opacity: 0.7;
  flex-shrink: 0;
  animation: tl-arrow-pulse 2s ease-in-out infinite;
}

@keyframes tl-arrow-pulse {
  0%,
  100% {
    opacity: 0.5;
    transform: translateX(0);
  }
  50% {
    opacity: 1;
    transform: translateX(2px);
  }
}

/* === Widget Title (optional) === */
.timeline-widget-title {
  font-size: 11px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 6px;
}

/* === Responsive: Mobile === */
@media (max-width: 480px) {
  .timeline-widget {
    gap: 4px;
    padding: 6px 2px;
  }

  .tl-node {
    min-width: 40px;
    padding: 5px 6px;
  }

  .tl-node.tl-self {
    min-width: 46px;
    padding: 6px 8px;
  }

  .tl-brig {
    font-size: 15px;
  }

  .tl-icon {
    font-size: 10px;
  }

  .tl-label {
    font-size: 8px;
  }

  .tl-value {
    font-size: 12px;
  }

  .tl-arrow {
    font-size: 13px;
  }
}

@media (max-width: 380px) {
  .timeline-widget {
    gap: 3px;
  }

  .tl-node {
    min-width: 36px;
    padding: 4px 5px;
  }

  .tl-brig {
    font-size: 13px;
  }

  .tl-arrow {
    font-size: 11px;
  }
}

/* === Free / day-off node === */
.tl-node.tl-free {
  background: linear-gradient(135deg, #10b981, #059669);
  border: 1px solid #059669;
}

/* === Segment tabs: Handoff | Cycle === */
.flow-segment-tabs {
  display: flex;
  gap: 6px;
  margin: 6px 0 10px;
  flex-wrap: wrap;
}

.flow-seg-btn {
  padding: 6px 12px;
  border-radius: 8px;
  border: 1px solid var(--border-cell, #363b4d);
  background: var(--panel-2, rgba(255, 255, 255, 0.04));
  color: var(--text-muted, #8b92a5);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.flow-seg-btn.active {
  background: var(--accent, #ff5722);
  border-color: var(--accent, #ff5722);
  color: #fff;
}

.flow-seg-btn:hover:not(.active) {
  border-color: var(--accent, #ff5722);
  color: var(--text, #e8eaf0);
}

.flow-segment-card .flow-seg-panel {
  min-height: 48px;
}

/* ================================================================
   GRAFIK GILLETTE - VARIABLES.CSS
   Part of modular CSS split (v3.8.0)
   ================================================================ */

* {
  box-sizing: border-box;
}

html,
body {
  overflow-x: hidden;
  max-width: 100vw;
}

:root {
  /* Defaults: R yellow, P green, N light blue, U soft teal (user-overridable via prefs.cellColors) */
  --color-R: #f1c40f;
  --color-R-border: #d4ac0d;
  --color-R-text: #3d2e00;
  --color-P: #82e0aa;
  --color-P-border: #27ae60;
  --color-P-text: #0e3d24;
  --color-N: #aed6f1;
  --color-N-border: #5dade2;
  --color-N-text: #1a3a52;
  --color-N-grad: linear-gradient(135deg, #aed6f1, #5dade2);
  --color-W: #ecf0f1;
  --color-W-text: #7f8c8d;
  --color-W-border: #ccd1d1;
  --color-U: #14b8a6;
  --color-U-border: #0f766e;
  --color-U-text: #ffffff;
  --color-U-grad: linear-gradient(135deg, #2dd4bf 0%, #0f766e 100%);
  --accent: #ff5722;

  --bg-body: linear-gradient(135deg, #1e3c72, #2a5298);
  --bg-container: #fff;
  --text-main: #222;
  --text-header: #1e3c72;
  --bg-controls: #f4f7fb;
  --bg-cell: #fafbfd;
  --border-cell: #ddd;
  --bg-info: linear-gradient(135deg, #f5f7fa, #e4ecf5);
  --bg-info-card: #fff;
  --text-muted: #666;
  --shadow-color: rgba(0, 0, 0, 0.15);
  --shadow-heavy: rgba(0, 0, 0, 0.35);
  --brig-A: #e74c3c;
  --brig-B: #27ae60;
  --brig-C: #2980b9;
  --brig-D: #8e44ad;
}
body.theme-dark {
  --bg-body: linear-gradient(135deg, #0a0e27, #1a1a2e);
  --bg-container: #1e222d;
  --text-main: #e0e0e0;
  --text-header: #64b5f6;
  --bg-controls: #2a2e3a;
  --bg-cell: #262a35;
  --border-cell: #3d4250;
  --bg-info: linear-gradient(135deg, #262a35, #1e222d);
  --bg-info-card: #2a2e3a;
  --text-muted: #999;
  --shadow-color: rgba(0, 0, 0, 0.5);
  --shadow-heavy: rgba(0, 0, 0, 0.8);
  --color-W: #2a2e3a;
  --color-W-text: #bdc3c7;
  --color-W-border: #3d4250;
}

body {
  font-family: 'Segoe UI', Tahoma, sans-serif;
  background: var(--bg-body);
  color: var(--text-main);
  margin: 0;
  padding: 15px;
  min-height: 100vh;
  transition: background 0.3s;
}
.container {
  max-width: min(1100px, calc(100vw - 30px));
  margin: 0 auto;
  background: var(--bg-container);
  border-radius: 14px;
  box-shadow: 0 12px 40px var(--shadow-color);
  padding: 20px;
  transition: background 0.3s;
  overflow-x: hidden;
}

/* ================================================================
   GRAFIK GILLETTE - VIEWS.CSS
   Part of modular CSS split (v3.8.0)
   ================================================================ */

/* === YEAR VIEW === */
.year-view {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-top: 10px;
  max-width: 100%;
  overflow: hidden;
}
.year-month {
  background: var(--bg-cell);
  border-radius: 12px;
  padding: 10px;
  border: 1px solid var(--border-cell);
  cursor: pointer;
  transition: all 0.2s;
  min-width: 0;
  overflow: hidden;
}
.year-month:hover {
  transform: translateY(-3px);
  box-shadow: 0 6px 16px var(--shadow-color);
}
.year-month h4 {
  margin: 0 0 6px;
  text-align: center;
  color: var(--text-header);
  font-size: 14px;
}
.mini-calendar {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 1px;
  min-width: 0;
}
.mini-day {
  border-radius: 3px;
  font-size: 9px;
  font-weight: bold;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255, 255, 255, 0.95);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
  min-width: 0;
  width: 100%;
  height: 18px;
  overflow: hidden;
  transition: transform 0.1s;
  cursor: pointer;
  position: relative;
}
.mini-day:hover {
  transform: scale(1.3);
  z-index: 5;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.4);
}
.mini-day.mR {
  background: var(--color-R);
}
.mini-day.mP {
  background: var(--color-P);
}
.mini-day.mN {
  background: var(--color-N);
}
.mini-day.mW {
  background: var(--color-W);
  color: var(--color-W-text);
  text-shadow: none;
}
.mini-day.mE {
  background: transparent;
  cursor: default;
}
.mini-day.mE:hover {
  transform: none;
  box-shadow: none;
}
.mini-day.mToday {
  outline: 2px solid #f1c40f;
  outline-offset: -1px;
}
.mini-day.mHoliday {
  box-shadow: inset 0 0 0 2px #c0392b;
}
.mini-day.mU {
  background: var(--color-U-grad) !important;
  color: #fff !important;
}
.mini-day.mDirty {
  outline: 2px dashed #f1c40f !important;
  outline-offset: -1px;
}
.mini-weekday {
  font-size: 8px;
  text-align: center;
  color: var(--text-muted);
  font-weight: bold;
  padding: 1px 0;
  min-width: 0;
}





/* === TABLE VIEW === */
.table-view {
  margin-top: 10px;
  overflow-x: visible;
  background: var(--bg-cell);
  border-radius: 12px;
  padding: 10px 8px;
  border: 1px solid var(--border-cell);
  animation: slideIn 0.3s ease-out;
}
.table-scroll {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  width: 100%;
  max-width: 100%;
  overscroll-behavior-x: contain;
  touch-action: pan-x pan-y;
}
.table-month-block {
  width: 100%;
}
.table-month-title,
.table-month-block h3 {
  text-align: center;
  color: var(--text-header);
  margin: 10px 0 8px;
  font-size: 17px;
  position: sticky;
  left: 0;
  right: 0;
  width: 100%;
  z-index: 2;
  background: var(--bg-cell);
  padding: 4px 0;
}
.brigade-table {
  /* B: compact rounded cells + separate spacing */
  border-collapse: separate;
  border-spacing: 2px;
  width: 100%;
  font-size: 12px;
  min-width: 0;
  table-layout: fixed;
}
.brigade-table th,
.brigade-table td {
  border: none;
  padding: 0;
  text-align: center;
  height: 40px;
  min-width: 0;
  position: relative;
  overflow: hidden;
  border-radius: 2px;
}
.brigade-table th {
  background: linear-gradient(180deg, #4b5563, #374151);
  color: #f3f4f6;
  font-weight: bold;
  font-size: 12px;
  padding: 6px 4px;
  position: sticky;
  top: 0;
  z-index: 3;
}
body:not(.theme-dark) .brigade-table th {
  background: linear-gradient(180deg, #e5e7eb, #d1d5db);
  color: #1f2937;
}
.brigade-table th.brig-label {
  background: var(--bg-controls);
  color: var(--text-header);
  position: sticky;
  left: 0;
  z-index: 5;
  min-width: 40px;
  width: 40px;
  padding: 2px 4px;
  font-size: 13px;
  border-radius: 2px;
  box-shadow: 2px 0 6px rgba(0, 0, 0, 0.25);
}
.brigade-table th.brig-label.A {
  border-left: 5px solid var(--brig-A);
}
.brigade-table th.brig-label.B {
  border-left: 5px solid var(--brig-B);
}
.brigade-table th.brig-label.C {
  border-left: 5px solid var(--brig-C);
}
.brigade-table th.brig-label.D {
  border-left: 5px solid var(--brig-D);
}
.brigade-table th.date-header {
  min-width: 0;
  padding: 3px 1px;
  font-size: 10px;
  line-height: 1.15;
  border-radius: 2px;
  height: 36px;
}
.brigade-table th.date-header .dh-day {
  display: block;
  font-size: 10px;
  opacity: 0.8;
  font-weight: normal;
}
.brigade-table th.date-header .dh-num {
  display: block;
  font-size: 11px;
  font-weight: bold;
}
.brigade-table th.date-header.weekend {
  background: linear-gradient(180deg, #4b5563, #374151);
  color: #fca5a5;
  box-shadow: inset 0 -2px 0 #ef4444;
}
body:not(.theme-dark) .brigade-table th.date-header.weekend {
  background: linear-gradient(180deg, #e5e7eb, #d1d5db);
  color: #b91c1c;
  box-shadow: inset 0 -2px 0 #ef4444;
}
.brigade-table th.date-header.today {
  background: linear-gradient(135deg, #f1c40f, #f39e0b);
  color: #111;
  box-shadow: inset 0 0 0 2px #d97706;
}
.brigade-table th.date-header.holiday {
  background: linear-gradient(180deg, #4b5563, #374151);
  color: #fecaca;
  box-shadow: inset 0 -2px 0 #f87171, inset 0 0 0 1px rgba(255,200,200,0.3);
}
body:not(.theme-dark) .brigade-table th.date-header.holiday {
  background: linear-gradient(180deg, #e5e7eb, #d1d5db);
  color: #991b1b;
  box-shadow: inset 0 -2px 0 #ef4444;
}
.brigade-table td.tc {
  font-weight: 800;
  font-size: 14px;
  color: #fff;
  cursor: pointer;
  transition: transform 0.1s, box-shadow 0.1s;
  border-radius: 2px;
}
.brigade-table td.tc:hover {
  transform: scale(1.08);
  z-index: 2;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.35);
}
body.edit-active .brigade-table td.tc {
  cursor: crosshair;
}
body.edit-active .brigade-table td.tc:hover {
  outline: 3px solid #e67e22;
  outline-offset: -3px;
  transform: scale(1.2);
}
.brigade-table td.tc-R {
  background: var(--color-R);
}
.brigade-table td.tc-P {
  background: var(--color-P);
}
.brigade-table td.tc-N {
  background: var(--color-N);
}
.brigade-table td.tc-W {
  background: transparent;
  color: var(--text-muted, #6b7c90);
  font-size: 11px;
  font-weight: 600;
  border: 1px dashed var(--border-cell);
  box-shadow: none;
}
.brigade-table td.tc-U {
  background: var(--color-U-grad);
  color: #fff;
  position: relative;
  font-size: 14px;
}
.brigade-table td.today-col {
  box-shadow: inset 0 0 0 2px #f1c40f;
}
/* D: weekend column tint */
.brigade-table td.weekend-col {
  box-shadow: inset 0 0 0 1px rgba(192, 57, 43, 0.35);
}
.brigade-table td.tc-W.weekend-col {
  background: rgba(90, 30, 30, 0.22);
  border: 1px dashed rgba(185, 70, 70, 0.5);
  color: #c4a4a4;
}
.brigade-table td.tc-R.weekend-col,
.brigade-table td.tc-P.weekend-col,
.brigade-table td.tc-N.weekend-col,
.brigade-table td.tc-U.weekend-col {
  box-shadow: inset 0 0 0 2px rgba(192, 57, 43, 0.45);
}
.brigade-table td.my-brigade {
  outline: 2px solid var(--accent);
