  function ensureFactoryDraftYear(year) {
    if (!factoryDrafts[year]) {
      factoryDrafts[year] = {};
      for (let m = 1; m <= 12; m++) {
        factoryDrafts[year][m] = { A: [], B: [], C: [], D: [] };
