  function countFactoryDraftChanges() {
    let count = 0;
    const walk = (obj) => {
      if (!obj || typeof obj !== 'object') return;
      if (Array.isArray(obj)) {
        obj.forEach((v) => {
          if (v !== null && v !== undefined && v !== '') count++;
        });
        return;
      }
      Object.keys(obj).forEach((k) => walk(obj[k]));
    };
    walk(factoryDrafts);
