      } catch (e) {
        /* ignoruj */
      }
    } else {
      prefs.notifications = false;
      savePrefs(prefs);
      showToast('warn', t('notificationsDisabled'));
    }
  });
}

function toggleNotifications() {
  if (areNotificationsEnabled()) {
