function renderFlowSegmentWidget(opts) {
  const {
    handoffHtml,
    cycleHtml,
    defaultMode, // 'handoff' | 'cycle'
  } = opts;
  const mode = defaultMode === 'cycle' ? 'cycle' : 'handoff';
  const handoffLabel = typeof t === 'function' ? t('flowModeHandoff') : 'Передача';
