function setStoredRemoteMtime(isoOrMs) {
  let ms = 0;
  if (typeof isoOrMs === 'number') ms = isoOrMs;
  else if (isoOrMs) ms = Date.parse(isoOrMs) || 0;
  if (ms > 0) localStorage.setItem(DRIVE_REMOTE_MT_KEY, String(ms));
