 * @returns {string}
 */
function formatTimeRange(from, to) {
  const fmt = (h) => {
    const hh = ((h % 24) + 24) % 24;
    return String(Math.floor(hh)).padStart(2, '0') + ':00';
  };
  return `${fmt(from)}–${fmt(to)}`;
